SELECT BATCH_ID, SOURCE_NAME, FILE_TYPE, STATUS, DECLARED_PARTS, DECLARED_RECORDS,
       DECLARED_AMOUNT, RETRY_COUNT, FAIL_REASON
FROM RECON_BATCH_SOURCE
WHERE BATCH_ID = #{batchId,jdbcType=VARCHAR}
  AND SOURCE_NAME = #{source,jdbcType=VARCHAR}
  AND FILE_TYPE = #{fileType,jdbcType=VARCHAR}

